<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $verticals = Simple_POS_Verticals::get_verticals(); ?> <div class='wrap simple-pos-wrap'> <h1><?php esc_html_e( 'Choose your business type', 'wp-pos-plugin' ) ; ?></h1> <p class='simple-pos-muted'><?php esc_html_e( 'We will seed sensible starting categories, taxes and sample products for your business. You can change everything later in Settings.', 'wp-pos-plugin' ) ; ?></p> <div class='simple-pos-vertical-grid'> <?php foreach ( $verticals as $slug => $v ) : ?> <div class='simple-pos-card simple-pos-vertical-card'> <h2><?php echo esc_html( $v['label'] ) ; ?></h2> <p class='simple-pos-muted'><?php echo esc_html( $v['description'] ) ; ?></p> <form method='post' action='<?php echo esc_url( admin_url( 'admin-post.php' ) ) ; ?>'> <?php wp_nonce_field( 'simple_pos_choose_vertical' ) ; ?> <input type='hidden' name='action' value='simple_pos_choose_vertical' /> <input type='hidden' name='vertical' value='<?php echo esc_attr( $slug ) ; ?>' /> <button type='submit' class='button button-primary'><?php esc_html_e( 'Use this', 'wp-pos-plugin' ) ; ?></button> </form> </div> <?php endforeach; ?> </div> </div> <style> .simple-pos-vertical-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px;margin-top:12px} .simple-pos-vertical-card{display:flex;flex-direction:column} .simple-pos-vertical-card form{margin-top:auto} </style> 
